import numpy as np
from scipy import ndimage as ndi
from collections import defaultdict

def loops(a):
    # Clockwise directed cell edges around visible binary ink.
    yy,xx=np.where(a);edges=defaultdict(list)
    for y,x in zip(yy,xx):
        if y==0 or not a[y-1,x]: edges[(2*x-1,2*y-1)].append((2*x+1,2*y-1))
        if x==a.shape[1]-1 or not a[y,x+1]: edges[(2*x+1,2*y-1)].append((2*x+1,2*y+1))
        if y==a.shape[0]-1 or not a[y+1,x]: edges[(2*x+1,2*y+1)].append((2*x-1,2*y+1))
        if x==0 or not a[y,x-1]: edges[(2*x-1,2*y+1)].append((2*x-1,2*y-1))
    out=[]
    while edges:
        start=next(iter(edges));p=[start];cur=start
        while True:
            nxt=edges[cur].pop()
            if not edges[cur]:del edges[cur]
            p.append(nxt);cur=nxt
            if cur==start:break
        if len(p)>8:
            xy=np.asarray(p)/2
            # Smooth the pixel stairs without appreciably altering the contour.
            xy=ndi.gaussian_filter1d(xy,1.,axis=0,mode='wrap')
            xy[-1]=xy[0];out.append(xy)
    return out

if __name__=='__main__':
 from PIL import Image
 m=np.array(Image.open('/app/target.png')).mean(2)<100
 L,n=ndi.label(m)
 for k in range(1,n+1):
  a=L==k;D=ndi.distance_transform_edt(a)
  cs=loops(D>1.4);print(k,len(cs),sum(np.linalg.norm(np.diff(c,axis=0),axis=1).sum() for c in cs))
PY
python /app/output/contours.py

